   476→        } finally {
   477→            long elapsed = (System.nanoTime() - startNanos) / 1_000_000;
   478→            parent.getMetrics().recordMcpInvocation(
   479→                    "maintain", workspaceRoot.toString(), elapsed, null, true, null);
   480→        }
   481→    }
