   483→    /**
   484→     * Formats and prints the 9-phase result table.
   485→     *
   486→     * <pre>
   487→     *   [1/9] Ingest ......................... 3 new files ingested
   488→     *   [2/9] Route .......................... 2 file(s) routed
   489→     *   ...
   490→     *   Done in 4.2s  |  3 changes applied
   491→     * </pre>
   492→     *
   493→     * <p>When {@code --quiet} is set, prints exactly one line:
   494→     * <pre>
   495→     *   2026-02-20T14:32:01Z  OK  9 phases, 17 changes, 4.2s  health=-1
   496→     * </pre>
   497→     *
   498→     * <p>When {@code --json} is set, prints a single JSON object to stdout.
   499→     */
   500→    private int printMaintainResult(MaintainResult result, Path workspaceRoot) {
   501→        // --json mode: machine-readable output
   502→        if (json) {
   503→            return printJsonResult(result, workspaceRoot);
   504→        }
   505→
   506→        // --quiet mode: single summary line
   507→        if (quiet) {
   508→            return printQuietResult(result);
   509→        }
   510→
   511→        // Normal table output
   512→        System.out.println();
   513→        AnsiOutput.printHeader("Synthesis - Maintain Workspace");
   514→        AnsiOutput.printInfo("Workspace: " + workspaceRoot);
   515→        System.out.println();
   516→
   517→        for (PhaseResult phase : result.phases()) {
   518→            String prefix = dryRun ? "(preview) " : "";
   519→            String phaseName = prefix + phase.name();
   520→            String tag = String.format("  [%d/9] %-" + (dryRun ? "20" : "10") + "s", phase.phaseNumber(), phaseName);
   521→
   522→            // Pad with dots to align the summary
   523→            int targetWidth = 45;
   524→            int dotsNeeded = Math.max(3, targetWidth - tag.length());
   525→            String dots = ".".repeat(dotsNeeded);
   526→
   527→            String status;
   528→            if (!phase.succeeded()) {
   529→                status = AnsiOutput.red("FAILED: " + phase.error());
   530→            } else if (phase.summary().startsWith("skipped")) {
   531→                status = AnsiOutput.dim(phase.summary());
   532→            } else {
   533→                status = phase.summary();
   534→            }
   535→
   536→            System.out.println(tag + " " + dots + " " + status);
   537→
   538→            // Verbose details
   539→            if (verbose && !phase.details().isEmpty()) {
   540→                for (String detail : phase.details()) {
   541→                    System.out.println("         " + AnsiOutput.dim(detail));
   542→                }
   543→            }
   544→        }
   545→
   546→        System.out.println();
   547→        double elapsedSec = result.elapsedMs() / 1000.0;
   548→        String changeSuffix = result.totalChanges() == 1 ? " change" : " changes";
   549→        System.out.printf("  Done in %.1fs  |  %d%s applied%n",
   550→                elapsedSec, result.totalChanges(), changeSuffix);
   551→        System.out.println();
   552→
   553→        // --dry-run footer
   554→        if (dryRun) {
   555→            System.out.println("  " + "─".repeat(55));
   556→            System.out.println("  No changes made. Remove --dry-run to apply.");
   557→            System.out.println();
   558→        }
   559→
   560→        return result.allSucceeded() ? 0 : 1;
   561→    }
