   617→    /**
   618→     * Walks transient directories and moves media files that have a strong identity
   619→     * match (score >= 0.5) to the matching permanent directory.
   620→     *
   621→     * <p>Uses the unified {@link DirectoryIdentityRouter} with {@code skipTransient=true}
   622→     * to avoid routing files back into other transient directories.
   623→     *
   624→     * <p><b>Threshold mapping (P1-05):</b> The old SubjectBasedRouter used threshold 0.7
   625→     * (pure token overlap * confidence). The DirectoryScorer provides richer scoring
   626→     * (type + format + pattern + token match), so an equivalent rebalance threshold
   627→     * is 0.5 (MODERATE confidence).
   628→     *
   629→     * @param workspaceRoot the workspace root directory
   630→     * @return the number of files moved
   631→     * @since v1.9.9 (issue #203), unified routing in P1-05
   632→     */
   633→    public int rebalanceTransient(Path workspaceRoot) throws IOException {
   634→        DirectoryIdentityParser idParser = new DirectoryIdentityParser();
   635→        DirectoryIdentityRouter router = new DirectoryIdentityRouter(workspaceRoot, null);
   636→        int moved = 0;
   637→
   638→        // Find all transient directories with .synthesis.md
   639→        List<Path> transientDirs = new ArrayList<>();
   640→        try (Stream<Path> walk = Files.walk(workspaceRoot, 6)) {
   641→            walk.filter(Files::isDirectory)
   642→                .filter(dir -> !dir.equals(workspaceRoot))
   643→                .filter(dir -> !dir.getFileName().toString().startsWith("."))
   644→                .filter(dir -> Files.exists(dir.resolve(".synthesis.md")))
   645→                .forEach(dir -> {
   646→                    DirectoryIdentity identity = idParser.parse(dir.resolve(".synthesis.md"));
   647→                    if (identity.transient_()) {
   648→                        transientDirs.add(dir);
   649→                    }
   650→                });
   651→        }
   652→
   653→        for (Path dir : transientDirs) {
   654→            List<Path> mediaFiles;
   655→            try (Stream<Path> files = Files.list(dir)) {
   656→                mediaFiles = files
   657→                        .filter(Files::isRegularFile)
   658→                        .filter(this::isMediaFile)
   659→                        .toList();
   660→            }
   661→
   662→            for (Path file : mediaFiles) {
   663→                // Use unified router with skipTransient=true, threshold 0.5
   664→                Optional<DirectoryIdentityRouter.RouteResult> match =
   665→                        router.route(file, 0.5, true);
   666→                if (match.isPresent() && !match.get().ambiguous()) {
   667→                    Path dest = match.get().directory();
   668→                    Files.createDirectories(dest);
   669→                    try {
   670→                        Files.move(file, dest.resolve(file.getFileName()));
   671→                        if (verbose) {
   672→                            System.out.println("    " + workspaceRoot.relativize(file)
   673→                                    + " → " + workspaceRoot.relativize(dest)
   674→                                    + " (score " + String.format("%.2f", match.get().score()) + ")");
   675→                        }
   676→                        moved++;
   677→
   678→                        // Issue #204: record forwarding pointer in source directory's .synthesis.md
   679→                        recordForwardingPointer(
   680→                                dir, file.getFileName().toString(),
   681→                                workspaceRoot.relativize(dest).toString(),
   682→                                match.get().score(), idParser);
   683→
   684→                    } catch (IOException e) {
   685→                        if (verbose) {
   686→                            System.err.println("    Could not move " + file.getFileName()
   687→                                    + ": " + e.getMessage());
   688→                        }
   689→                    }
   690→                }
   691→            }
   692→        }
   693→
   694→        return moved;
   695→    }
   696→
   697→    /**
   698→     * Records a forwarding pointer in the source directory's {@code .synthesis.md}
   699→     * when a file is moved during rebalance.
   700→     *
   701→     * <p>The pointer captures: which file moved, where it went, when, by what
   702→     * operation, and the routing score as a reason string.
   703→     *
   704→     * @param sourceDir the directory the file was moved from
   705→     * @param fileName  the name of the file that was moved
   706→     * @param movedTo   the workspace-relative path of the destination directory
   707→     * @param score     the routing score that triggered the move
   708→     * @param parser    the parser to use for read/write
   709→     * @since v1.9.9 (issue #204)
   710→     */
   711→    void recordForwardingPointer(Path sourceDir, String fileName,
   712→                                  String movedTo, double score,
   713→                                  DirectoryIdentityParser parser) {
   714→        try {
   715→            Path synthesisFile = sourceDir.resolve(".synthesis.md");
   716→            DirectoryIdentity existing = parser.parse(synthesisFile);
   717→
   718→            ForwardingPointer pointer = new ForwardingPointer(
   719→                    fileName,
   720→                    movedTo,
   721→                    java.time.Instant.now(),
   722→                    "rebalance",
   723→                    "score " + String.format("%.2f", score)
   724→            );
   725→
   726→            // Append the new pointer to the existing moved_files list
   727→            List<ForwardingPointer> updatedPointers = new ArrayList<>(existing.movedFiles());
   728→            updatedPointers.add(pointer);
   729→
   730→            DirectoryIdentity updated = new DirectoryIdentity(
   731→                    existing.acceptsTypes(),
   732→                    existing.acceptsFormats(),
   733→                    existing.acceptsPatterns(),
   734→                    existing.scopeLevel(),
   735→                    existing.scopeOrganization(),
   736→                    existing.scopeEntity(),
   737→                    existing.confidence(),
   738→                    existing.lastSynced(),
   739→                    existing.source(),
   740→                    existing.description(),
   741→                    existing.rejectsTypes(),
   742→                    existing.aliases(),
   743→                    existing.transient_(),
   744→                    updatedPointers
   745→            );
   746→
   747→            parser.write(synthesisFile, updated);
   748→        } catch (Exception e) {
   749→            if (verbose) {
   750→                System.err.println("    Warning: Could not record forwarding pointer for "
   751→                        + fileName + ": " + e.getMessage());
   752→            }
   753→        }
   754→    }
