   756→    /**
   757→     * Returns true if the file is a media file (video, audio, image).
   758→     */
   759→    private boolean isMediaFile(Path file) {
   760→        String name = file.getFileName().toString();
   761→        int dot = name.lastIndexOf('.');
   762→        if (dot < 0 || dot == name.length() - 1) return false;
   763→        String ext = name.substring(dot + 1).toLowerCase(java.util.Locale.ROOT);
   764→        return MediaTypes.MEDIA_EXTENSIONS.contains(ext);
   765→    }
