   767→    /**
   768→     * Walks the archive directory and moves any file that scores >= 0.7 against
   769→     * a non-ambiguous identity-declared directory back into that active directory.
   770→     *
   771→     * <p>Excludes files inside {@code .git} directories and frozen snapshot subtrees
   772→     * (top-level archive subdirectories starting with {@code old-}, {@code snapshot-},
   773→     * or {@code frozen-}).
   774→     *
   775→     * @return the number of files moved
   776→     */
   777→    public int rebalanceArchive(Path archiveDir, DirectoryIdentityRouter router, Path workspaceRoot)
   778→            throws IOException {
   779→        int moved = 0;
   780→        List<Path> archiveFiles = new ArrayList<>();
   781→        try (Stream<Path> walk = Files.walk(archiveDir)) {
   782→            walk.filter(Files::isRegularFile)
   783→                .filter(p -> !MaintainOrchestrator.isInsideGitDir(p))
   784→                .filter(p -> !MaintainOrchestrator.isFrozenSubtree(p, archiveDir))
   785→                .forEach(archiveFiles::add);
   786→        }
   787→        for (Path file : archiveFiles) {
   788→            Optional<DirectoryIdentityRouter.RouteResult> routed = router.route(file, 0.7);
   789→            if (routed.isPresent() && !routed.get().ambiguous()) {
   790→                Path dest = routed.get().directory();
   791→                Files.createDirectories(dest);
   792→                try {
   793→                    Files.move(file, dest.resolve(file.getFileName()));
   794→                    if (verbose) {
   795→                        System.out.println("    " + workspaceRoot.relativize(file)
   796→                                + " → " + workspaceRoot.relativize(dest));
   797→                    }
   798→                    moved++;
   799→                } catch (IOException e) {
   800→                    if (verbose) {
   801→                        System.err.println("    Could not move " + file.getFileName()
   802→                                + ": " + e.getMessage());
   803→                    }
   804→                }
   805→            }
   806→        }
   807→        return moved;
   808→    }
