   905→                    }
   906→                }
   907→            }
   908→
   909→            // Re-index modified files
   910→            for (FileMetadata fm : changes.modified()) {
   911→                try {
   912→                    AnalysisResult analysis = analyzers.analyze(fm);
   913→                    String subWorkspace = subWsResolver.resolve(fm.relativePath());
   914→                    index.addDocument(fileIndexer.createDocument(fm, analysis,
