   993→    /**
   994→     * Fetches remote changes for all client codebases discovered via OrganizationRegistry.
   995→     * Also writes .synthesis-last-activity files for dashboard consumption.
   996→     */
   997→    private void fetchClientCodebases(Path workspaceRoot) {
   998→        OrganizationRegistry registry = loadOrgRegistryForMaintain(workspaceRoot);
   999→        if (registry == null || !registry.hasOrganizations()) {
  1000→            if (verbose) {
  1001→                AnsiOutput.printInfo("No organization registry found -- skipping git fetch.");
  1002→            }
  1003→            return;
  1004→        }
  1005→
  1006→        // Collect all unique codebase paths
  1007→        Set<String> seen = new HashSet<>();
  1008→        List<CodebaseFetchTarget> targets = new ArrayList<>();
  1009→        for (Organization org : registry.getOrganizations()) {
  1010→            for (Client client : org.getClients()) {
  1011→                for (String codebasePath : client.getCodebases()) {
  1012→                    if (seen.add(codebasePath)) {
  1013→                        targets.add(new CodebaseFetchTarget(client.getName(), codebasePath));
  1014→                    }
  1015→                }
  1016→            }
  1017→        }
  1018→
  1019→        if (targets.isEmpty()) {
  1020→            if (verbose) {
  1021→                AnsiOutput.printInfo("No client codebases configured -- skipping git fetch.");
