  1088→            ProcessBuilder pb = new ProcessBuilder(
  1089→                    "git", "log", "-1", "--format=%aI");
  1090→            pb.directory(cbPath.toFile());
  1091→            pb.redirectErrorStream(true);
  1092→            Process process = pb.start();
  1093→            String dateStr = null;
  1094→            try (BufferedReader reader = new BufferedReader(
  1095→                    new InputStreamReader(process.getInputStream()))) {
  1096→                dateStr = reader.readLine();
  1097→            }
  1098→            process.waitFor();
